+public class CidrTests extends ScriptTestCase {
+    public void testContains() {
+        Object bool = exec("CIDR c = new CIDR('10.1.1.0/23'); c.contains('10.1.1.128') && c.contains('10.1.0.255')");
+        assertEquals(Boolean.TRUE, bool);
